window.RF_FULL=window.RF_FULL||{};window.RF_FULL["fz54muzei"]=[
["0","Преамбула и список изменений","","2025-07-31","РОССИЙСКАЯ ФЕДЕРАЦИЯ ФЕДЕРАЛЬНЫЙ ЗАКОН (Особенности применения настоящего Федерального закона - Федеральный закон от 23.02.2011 № 19-ФЗ)\nО Музейном фонде Российской Федерации и музеях в Российской Федерации\nПринят Государственной Думой 24 апреля 1996 года\nСписок изменяющих документов(В редакции федеральных законов от 10.01.2003 № 15-ФЗ, от 22.08.2004 № 122-ФЗ, от 26.06.2007 № 118-ФЗ, от 23.07.2008 № 160-ФЗ, от 08.05.2010 № 83-ФЗ, от 23.02.2011 № 19-ФЗ, от 01.12.2014 № 419-ФЗ, от 03.07.2016 № 357-ФЗ, от 28.12.2017 № 435-ФЗ, от 27.12.2018 № 515-ФЗ, от 11.06.2021 № 167-ФЗ, от 11.06.2021 № 170-ФЗ, от 24.07.2023 № 327-ФЗ, от 12.12.2023 № 581-ФЗ, от 31.07.2025 № 304-ФЗ)"],
["1","Сфера применения настоящего Федерального закона","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","2023-12-12","Статья 1. Сфера применения настоящего Федерального закона\nНастоящий Федеральный закон определяет особенности правового положения Музейного фонда Российской Федерации, а также особенности создания и правовое положение музеев в Российской Федерации.\nНастоящий Федеральный закон распространяется на все действующие и вновь создаваемые музеи в Российской Федерации и иные организации, а также физических лиц, в собственности, во владении или в пользовании которых находятся музейные предметы и музейные коллекции. (В редакции Федерального закона от 12.12.2023 № 581-ФЗ)"],
["2","Законодательство Российской Федерации о Музейном фонде Российской Федерации и музеях в Российской Федерации","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","","Статья 2. Законодательство Российской Федерации о Музейном фонде Российской Федерации и музеях в Российской Федерации\nЗаконодательство Российской Федерации о Музейном фонде Российской Федерации и музеях в Российской Федерации состоит из Конституции Российской Федерации, Основ законодательства Российской Федерации о культуре, настоящего Федерального закона, принимаемых в соответствии с ним федеральных законов и иных нормативных правовых актов Российской Федерации, законов и иных нормативных правовых актов субъектов Российской Федерации.\nЗаконы и иные нормативные правовые акты субъектов Российской Федерации, регулирующие отношения, указанные в части первой статьи 1 настоящего Федерального закона, не могут противоречить настоящему Федеральному закону.\nВ случае противоречия между настоящим Федеральным законом и иным актом, принимаемым в Российской Федерации, действует настоящий Федеральный закон."],
["3","Основные понятия","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","2017-12-28","Статья 3. Основные понятия\nДля целей настоящего Федерального закона используются следующие основные понятия и термины:\nкультурные ценности - движимые предметы материального мира независимо от времени их создания, имеющие историческое, художественное, научное или культурное значение; (В редакции Федерального закона от 28.12.2017 № 435-ФЗ)\nмузейный предмет - культурная ценность, качество либо особые признаки которой делают необходимым для общества ее сохранение, изучение и публичное представление;\nмузейная коллекция - совокупность культурных ценностей, которые приобретают свойства музейного предмета, только будучи соединенными вместе в силу характера своего происхождения, либо видового родства, либо по иным признакам;\nМузейный фонд Российской Федерации - совокупность подлежащих государственному учету и постоянно находящихся на территории Российской Федерации музейных предметов и музейных коллекций, гражданский оборот которых допускается с соблюдением ограничений, установленных настоящим Федеральным законом; (В редакции Федерального закона от 03.07.2016 № 357-ФЗ)\nмузей - некоммерческое учреждение культуры, созданное собственником для хранения, изучения и публичного представления музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации, а также для достижения иных целей, определенных настоящим Федеральным законом; (В редакции федеральных законов от 23.02.2011 № 19-ФЗ; от 03.07.2016 № 357-ФЗ)\nнегосударственный музей федерального значения - музей, особый статус которого определяется актом Правительства Российской Федерации в соответствии с настоящим Федеральным законом; (Дополнение абзацем - Федеральный закон от 28.12.2017 № 435-ФЗ)\nхранение - один из основных видов деятельности музея, предполагающий создание материальных и юридических условий, при которых обеспечивается сохранность музейного предмета и музейной коллекции;\nпубликация - одна из основных форм деятельности музея, предполагающая все виды представления обществу музейных предметов и музейных коллекций путем публичного показа, воспроизведения в печатных изданиях, на электронных и других видах носителей, размещения сведений о музейных предметах и музейных коллекциях в информационно-телекоммуникационной сети \"Интернет\". (В редакции Федерального закона от 03.07.2016 № 357-ФЗ)"],
["4","Государственное регулирование в сфере музеев и Музейного фонда Российской Федерации","ГЛАВА I. ОБЩИЕ ПОЛОЖЕНИЯ","2021-06-11","Статья 4. Государственное регулирование в сфере музеев и Музейного фонда Российской Федерации\nОт имени Российской Федерации имущественные и неимущественные личные права и обязанности, а также федеральный государственный контроль (надзор) за состоянием Музейного фонда Российской Федерации осуществляет федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере культуры (далее - федеральный орган исполнительной власти в сфере культуры). (В редакции федеральных законов от 03.07.2016 № 357-ФЗ, от 11.06.2021 № 170-ФЗ)\nОт имени субъектов Российской Федерации имущественные и неимущественные личные права и обязанности, а также региональный государственный контроль (надзор) за состоянием Музейного фонда Российской Федерации осуществляют уполномоченные органы государственной власти субъектов Российской Федерации, на которые возложено государственное регулирование в области культуры. (В редакции Федерального закона от 11.06.2021 № 170-ФЗ)"],
["5","Музейный фонд Российской Федерации как часть культурного наследия народов Российской Федерации","ГЛАВА II. МУЗЕЙНЫЙ ФОНД РОССИЙСКОЙ ФЕДЕРАЦИИ","2023-12-12","Статья 5. Музейный фонд Российской Федерации как часть культурного наследия народов Российской Федерации\nМузейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации, являются неотъемлемой частью культурного наследия народов Российской Федерации.\nМузейный фонд Российской Федерации состоит из государственной части Музейного фонда Российской Федерации и негосударственной части Музейного фонда Российской Федерации. (Дополнение частью - Федеральный закон от 03.07.2016 № 357-ФЗ)\nМузейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации, могут находиться в государственной, муниципальной, частной или иных формах собственности. (Дополнение частью - Федеральный закон от 03.07.2016 № 357-ФЗ)\nМузеи, иные организации, физические лица, в собственности, во владении или в пользовании которых находятся музейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации, обязаны обеспечить в порядке, установленном едиными правилами организации комплектования, учета, хранения и использования музейных предметов и музейных коллекций, утверждаемыми федеральным органом исполнительной власти в сфере культуры (далее - единые правила):\nфактическое наличие и физическую сохранность музейных предметов и музейных коллекций, сведения о которых содержатся в учетной документации, связанной с этими музейными предметами и музейными коллекциями, а также проведение реставрационных работ лицами, прошедшими в федеральном органе исполнительной власти в сфере культуры аттестацию на право проведения таких работ в отношении музейных предметов и музейных коллекций в порядке, установленном федеральным органом исполнительной власти в сфере культуры; (В редакции Федерального закона от 12.12.2023 № 581-ФЗ)\nбезопасность музейных предметов и музейных коллекций, включая наличие присвоенных им учетных обозначений и охранной маркировки музейных предметов и музейных коллекций;\nучет музейных предметов и музейных коллекций, ведение и сохранность учетной документации, связанной с этими музейными предметами и музейными коллекциями.\n(Дополнение частью - Федеральный закон от 03.07.2016 № 357-ФЗ)\nПоложение о Музейном фонде Российской Федерации утверждается федеральным органом исполнительной власти в сфере культуры (далее - положение о Музейном фонде). (Дополнение частью - Федеральный закон от 03.07.2016 № 357-ФЗ)"],
["6","Государственный учет музейных предметов и музейных коллекций, в том числе включенных в состав Музейного фонда Российской Федерации","ГЛАВА II. МУЗЕЙНЫЙ ФОНД РОССИЙСКОЙ ФЕДЕРАЦИИ","2023-12-12","Статья 6. Государственный учет музейных предметов и музейных коллекций, в том числе включенных в состав Музейного фонда Российской Федерации\nМузейные предметы и музейные коллекции, в том числе включенные в состав Музейного фонда Российской Федерации, независимо от того, в чьей собственности или во владении они находятся, подлежат государственному учету.\nГосударственный учет музейных предметов и музейных коллекций, в том числе включенных в состав Музейного фонда Российской Федерации (далее - государственный учет), представляет собой комплекс мер, обеспечивающих идентификацию и предметно-количественный учет музейных предметов и музейных коллекций, в том числе включенных в состав Музейного фонда Российской Федерации, в целях их правовой защиты и государственного контроля.\nГосударственный учет осуществляется:\nпри включении музейных предметов и музейных коллекций в состав Музейного фонда Российской Федерации;\nпри исключении музейных предметов и музейных коллекций из состава Музейного фонда Российской Федерации;\nпри внесении изменений в сведения о музейном предмете или музейной коллекции, включенных в состав Музейного фонда Российской Федерации;\nпри осуществлении сделок с музейными предметами и музейными коллекциями, включенными в состав Музейного фонда Российской Федерации;\nв иных предусмотренных законодательством Российской Федерации случаях.\nГосударственный учет состоит из первичного государственного учета (далее - первичный учет) и централизованного государственного учета (далее - централизованный учет).\nПервичный учет осуществляется государственными и муниципальными музеями, государственными и муниципальными организациями, во владении или в пользовании которых находятся музейные предметы и музейные коллекции, в том числе включенные в состав Музейного фонда Российской Федерации, в соответствии с частями девятой - тринадцатой настоящей статьи.\nПервичный учет музейных предметов и музейных коллекций, находящихся в негосударственной (кроме муниципальной) собственности, осуществляется в порядке, установленном положением о Музейном фонде.\nЦентрализованный учет осуществляется посредством внесения сведений в Государственный каталог Музейного фонда Российской Федерации (далее также - государственный каталог) в соответствии со статьей 10 настоящего Федерального закона.\nПри осуществлении государственного учета в целях включения музейных предметов и музейных коллекций в состав Музейного фонда Российской Федерации реализуются процедуры первичного учета и централизованного учета.\nПервичный учет включает в себя:\nэкспертизу культурных ценностей в целях отнесения их к музейным предметам и музейным коллекциям (далее - экспертиза культурных ценностей);\nпервичную регистрацию музейных предметов и музейных коллекций, подлежащих включению в состав Музейного фонда Российской Федерации (далее также - первичная регистрация).\nВ государственных и муниципальных музеях экспертиза культурных ценностей и экспертиза музейных предметов и музейных коллекций, в том числе включенных в состав Музейного фонда Российской Федерации, в целях настоящего Федерального закона проводятся уполномоченным коллегиальным органом музея, в собственности или во владении которого находятся музейные предметы и музейные коллекции, в том числе подлежащие включению в состав Музейного фонда Российской Федерации. Сроки проведения экспертизы культурных ценностей устанавливаются положением о Музейном фонде. (В редакции Федерального закона от 12.12.2023 № 581-ФЗ)\nВ иных организациях, кроме государственных и муниципальных музеев, экспертиза культурных ценностей и экспертиза музейных предметов и музейных коллекций, в том числе включенных в состав Музейного фонда Российской Федерации, в целях настоящего Федерального закона проводятся в порядке, установленном положением о Музейном фонде.\nПервичная регистрация проводится музеями, иными организациями, в собственности или во владении которых находятся музейные предметы и музейные коллекции, в установленном едиными правилами порядке на основании приказа руководителя музея, иной организации, в собственности или во владении которых находятся музейные предметы и музейные коллекции, в том числе подлежащие включению в состав Музейного фонда Российской Федерации, в срок не более 30 календарных дней со дня утверждения результатов экспертизы культурных ценностей.\nДля осуществления первичной регистрации сведения о музейных предметах и музейных коллекциях вносятся в книгу поступлений основного фонда музея (главную инвентарную книгу музея), порядковый номер записи в которой является неотъемлемым учетным обозначением музейного предмета или музейной коллекции.\nОсновной фонд музея представляет собой совокупность зарегистрированных в книге поступлений основного фонда музея (главной инвентарной книге музея) и хранящихся в музее, иной организации музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации.\nФорма книги поступлений основного фонда музея (главной инвентарной книги музея), состав и порядок внесения в нее сведений устанавливаются едиными правилами.\nЦентрализованный учет включает в себя:\nвнесение сведений о музейных предметах и музейных коллекциях, подлежащих включению в состав Музейного фонда Российской Федерации, в государственный каталог;\nприсвоение каждому музейному предмету и каждой музейной коллекции уникального идентификационного номера.\n(Статья в редакции Федерального закона от 03.07.2016 № 357-ФЗ)"],
["7","Собрание музея","ГЛАВА II. МУЗЕЙНЫЙ ФОНД РОССИЙСКОЙ ФЕДЕРАЦИИ","2023-12-12","Статья 7. Собрание музея\nСобрание музея состоит из находящихся на хранении в музее музейных предметов и музейных коллекций, включенных в основной и иные фонды музея, а также предметов и документов архивного, библиотечного, кино-, фотофондов и иных фондов, которые служат целям его создания.\nПеречень фондов, в которые входят музейные предметы и музейные коллекции, иные предметы и документы, образующие собрание музея, устанавливается едиными правилами.\nОтражение музейных предметов и музейных коллекций на балансе музея не допускается.\nМузейная коллекция является неделимой.\nСобрание музея формируется на основании концепции комплектования собрания музея, которая утверждается руководителем музея по согласованию с учредителем музея. Концепция комплектования собрания музея основывается на принципе целостности и единства собрания музея и содержит в том числе тематику собрания музея, принципы комплектования собрания музея, критерии включения музейных предметов и музейных коллекций в собрание музея, а также цели развития музея. Требования к порядку согласования учредителем музея концепции комплектования собрания музея устанавливаются едиными правилами.\nВ целях обеспечения сохранности и целостности собрания музея в порядке и сроки, которые установлены едиными правилами, осуществляются проверка фактического наличия и физической сохранности музейных предметов и музейных коллекций и сверка сведений о музейных предметах и музейных коллекциях, внесенных в государственный каталог, со сведениями, содержащимися в учетной документации, связанной с этими музейными предметами и музейными коллекциями, с учетом внешнего вида и иных индивидуализирующих характеристик музейных предметов и музейных коллекций.\nМузейные предметы и музейные коллекции, не включенные в состав Музейного фонда Российской Федерации, подлежат учету, хранению и использованию в порядке, установленном едиными правилами. Указанные музейные предметы и музейные коллекции, находящиеся в оперативном управлении музея, подлежат отнесению к особо ценному движимому имуществу музея.\nПрекращение права оперативного управления музея в отношении музейных предметов и музейных коллекций из собрания музея допускается в соответствии с Гражданским кодексом Российской Федерации с учетом особенностей, установленных настоящим Федеральным законом, при условии, что прекращение указанного права не повлечет за собой необходимость изменения концепции комплектования собрания музея. Музейные предметы и музейные коллекции, находящиеся в музее на праве оперативного управления, могут быть изъяты собственником только в случае их использования не по назначению и при соблюдении условий, не лишающих музей возможности осуществлять деятельность, цели, предмет и виды которой определены его уставом.\nНа имущество, составляющее собрание музея, не может быть обращено взыскание по обязательствам музея.\nПри смене собственника имущества, принадлежащего музею на праве оперативного управления, изменении ведомственной принадлежности музея в отношении собрания такого музея обеспечивается принцип целостности и единства, разделение (дробление) собрания музея на части не допускается.\n(Статья в редакции Федерального закона от 12.12.2023 № 581-ФЗ)"],
["8","Включение музейных предметов и музейных коллекций в состав Музейного фонда Российской Федерации","ГЛАВА II. МУЗЕЙНЫЙ ФОНД РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 8. Включение музейных предметов и музейных коллекций в состав Музейного фонда Российской Федерации\nМузейные предметы и музейные коллекции считаются включенными в состав Музейного фонда Российской Федерации со дня их регистрации в государственном каталоге.\nВключение музейных предметов и музейных коллекций в состав Музейного фонда Российской Федерации осуществляется в порядке, установленном статьями 6 и 10 настоящего Федерального закона.\nВключение музейных предметов и музейных коллекций, находящихся в частной собственности, в состав Музейного фонда Российской Федерации осуществляется федеральным органом исполнительной власти в сфере культуры по заявлению собственника в порядке, установленном положением о Музейном фонде.\n(Статья в редакции Федерального закона от 03.07.2016 № 357-ФЗ)"],
["9","Исключение музейных предметов и музейных коллекций из состава Музейного фонда Российской Федерации","ГЛАВА II. МУЗЕЙНЫЙ ФОНД РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 9. Исключение музейных предметов и музейных коллекций из состава Музейного фонда Российской Федерации\nМузейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации, исключению из состава Музейного фонда Российской Федерации не подлежат, за исключением случаев утраты, разрушения, а также отсутствия историко-культурной, художественной, научной и иной их ценности, установленного экспертизой, проведенной в отношении этих музейных предметов и музейных коллекций, наличия судебного решения, вступившего в законную силу.\nИсключение музейных предметов и музейных коллекций из состава Музейного фонда Российской Федерации осуществляется с учетом заключения экспертизы, проведенной в их отношении, по решению федерального органа исполнительной власти в сфере культуры в порядке, установленном положением о Музейном фонде.\nМузейные предметы и музейные коллекции считаются исключенными из состава Музейного фонда Российской Федерации с момента внесения соответствующей записи в государственный каталог.\n(Статья в редакции Федерального закона от 03.07.2016 № 357-ФЗ)"],
["10","Государственный каталог Музейного фонда Российской Федерации","ГЛАВА II. МУЗЕЙНЫЙ ФОНД РОССИЙСКОЙ ФЕДЕРАЦИИ","2025-07-31","Статья 10. Государственный каталог Музейного фонда Российской Федерации\nГосударственный каталог представляет собой федеральную государственную информационную систему государственного учета музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации, созданную в целях обеспечения их правовой защиты и государственного контроля.\nГосударственный каталог состоит из:\nреестра музеев, иных организаций, физических лиц, в собственности, во владении или в пользовании которых находятся музейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации (далее - реестр музеев);\nреестра музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации (далее - реестр Музейного фонда);\nреестра сделок с музейными предметами и музейными коллекциями, включенными в состав Музейного фонда Российской Федерации (далее - реестр сделок);\nреестра специальных разрешений на отчуждение или переход от одного лица к другому в порядке универсального правопреемства либо иным способом музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации (далее - реестр специальных разрешений). (Дополнение абзацем - Федеральный закон от 31.07.2025 № 304-ФЗ)\nВедение государственного каталога осуществляется федеральным органом исполнительной власти в сфере культуры, исполняющим функции оператора государственного каталога. На основании решения федерального органа исполнительной власти в сфере культуры полномочия по ведению государственного каталога могут быть переданы подведомственному учреждению.\nПеречень сделок, подлежащих регистрации в государственном каталоге, состав сведений, подлежащих внесению в реестр музеев, реестр Музейного фонда, реестр сделок, реестр специальных разрешений, порядок их внесения, а также состав сведений, размещаемых на официальном сайте государственного каталога в информационно-телекоммуникационной сети \"Интернет\", порядок функционирования государственного каталога, порядок хранения, обработки и использования содержащейся в государственном каталоге информации, требования к обеспечению мер по защите указанной информации устанавливаются положением о Государственном каталоге Музейного фонда Российской Федерации (далее - положение о государственном каталоге), которое утверждается федеральным органом исполнительной власти в сфере культуры. (В редакции Федерального закона от 31.07.2025 № 304-ФЗ)\nВнесение в реестр Музейного фонда сведений о музейных предметах и музейных коллекциях в случаях, определенных абзацами вторым и четвертым части третьей статьи 6 настоящего Федерального закона, осуществляется государственными и муниципальными музеями, иными государственными и муниципальными организациями, во владении или в пользовании которых находятся музейные предметы и музейные коллекции, подлежащие включению в состав Музейного фонда Российской Федерации, путем электронного взаимодействия с оператором государственного каталога в порядке, установленном положением о государственном каталоге.\nВнесение в государственный каталог сведений о музейных предметах и музейных коллекциях, находящихся во владении или в пользовании государственных и муниципальных музеев, иных государственных и муниципальных организаций, и сделках с ними в случаях, определенных абзацами третьим, пятым и шестым части третьей статьи 6 настоящего Федерального закона, осуществляется федеральным органом исполнительной власти в сфере культуры в порядке, установленном положением о государственном каталоге.\nВнесение в государственный каталог сведений о музейных предметах и музейных коллекциях, находящихся в частной собственности, и о сделках с ними осуществляется федеральным органом исполнительной власти в сфере культуры в порядке, установленном положением о государственном каталоге.\nСодержащиеся в реестре Музейного фонда сведения о музейных предметах и музейных коллекциях, включенных в состав Музейного фонда Российской Федерации, являются общедоступными, за исключением сведений, распространение которых ограничено законодательством Российской Федерации, и предоставляются гражданам бесплатно путем их размещения на официальном сайте государственного каталога в информационно-телекоммуникационной сети \"Интернет\" в порядке, установленном положением о государственном каталоге.\n(Статья в редакции Федерального закона от 03.07.2016 № 357-ФЗ)"],
["11","Вывоз из Российской Федерации музейных предметов и музейных коллекций","ГЛАВА II. МУЗЕЙНЫЙ ФОНД РОССИЙСКОЙ ФЕДЕРАЦИИ","2023-07-24","Статья 11. Вывоз из Российской Федерации музейных предметов и музейных коллекций\nМузейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации, вывозу из Российской Федерации не подлежат.\nВременный вывоз данных предметов регулируется Законом Российской Федерации \"О вывозе и ввозе культурных ценностей\".\nНаправление музеями в федеральный орган исполнительной власти в сфере культуры документов, необходимых для выдачи заключения (разрешительного документа) на временный вывоз музейных предметов, включенных в состав Музейного фонда Российской Федерации, и выдача музеям федеральным органом исполнительной власти в сфере культуры заключения (разрешительного документа) на временный вывоз музейных предметов, включенных в состав Музейного фонда Российской Федерации, могут осуществляться посредством Государственного каталога. (Дополнение частью - Федеральный закон от 24.07.2023 № 327-ФЗ)"],
["12","Особенности гражданского оборота музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации","ГЛАВА II. МУЗЕЙНЫЙ ФОНД РОССИЙСКОЙ ФЕДЕРАЦИИ","2025-07-31","Статья 12. Особенности гражданского оборота музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации\nМузейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации, могут отчуждаться или переходить от одного лица к другому в порядке универсального правопреемства либо иным способом только по специальному разрешению федерального органа исполнительной власти в сфере культуры (далее - специальное разрешение). Специальное разрешение предоставляется путем внесения соответствующей записи в реестр специальных разрешений. Порядок предоставления специального разрешения устанавливается положением о Музейном фонде. (В редакции федеральных законов от 03.07.2016 № 357-ФЗ, от 31.07.2025 № 304-ФЗ)"],
["12.1","Особенности учета и хранения отдельных видов музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации","ГЛАВА II. МУЗЕЙНЫЙ ФОНД РОССИЙСКОЙ ФЕДЕРАЦИИ","2021-06-11","Статья 12.1. Особенности учета и хранения отдельных видов музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации\nМузеи, иные организации, физические лица, в собственности, во владении или в пользовании которых находятся музейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации и содержащие в своем составе драгоценные камни и драгоценные металлы или относящиеся к предметам геологии, зоологии, археологии, палеонтологии, к оружию, государственным наградам, государственным знакам почтовой оплаты и иным видам объектов гражданских прав, учет, хранение и использование которых подпадают под правовое регулирование законодательства Российской Федерации в соответствующих сферах, осуществляют учет, обеспечивают хранение и использование таких музейных предметов и музейных коллекций с учетом требований законодательства Российской Федерации. Правила организации учета, хранения и использования музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации и содержащих в своем составе драгоценные металлы и драгоценные камни, утверждаются федеральным органом исполнительной власти в сфере культуры по согласованию с федеральным органом исполнительной власти, осуществляющим функции по выработке государственной политики и нормативно-правовому регулированию в сфере производства, переработки и обращения драгоценных металлов и драгоценных камней. (В редакции Федерального закона от 11.06.2021 № 167-ФЗ)\nУчет и хранение включенных в государственную часть Музейного фонда Российской Федерации музыкальных инструментов, относящихся к Государственной коллекции уникальных музыкальных инструментов Российской Федерации (далее - государственная коллекция музыкальных инструментов), регулируются настоящим Федеральным законом, положением о государственной коллекции музыкальных инструментов, которое утверждается федеральным органом исполнительной власти в сфере культуры.\n(Дополнение статьей - Федеральный закон от 03.07.2016 № 357-ФЗ)"],
["12.2","Государственный контроль (надзор) за состоянием Музейного фонда Российской Федерации","ГЛАВА II. МУЗЕЙНЫЙ ФОНД РОССИЙСКОЙ ФЕДЕРАЦИИ","2021-06-11","Статья 12.2. Государственный контроль (надзор) за состоянием Музейного фонда Российской Федерации\nГосударственный контроль (надзор) за состоянием Музейного фонда Российской Федерации осуществляется посредством:\nфедерального государственного контроля (надзора) за состоянием Музейного фонда Российской Федерации, осуществляемого федеральным органом исполнительной власти в сфере культуры в соответствии с положением, утверждаемым Правительством Российской Федерации;\nрегионального государственного контроля (надзора) за состоянием Музейного фонда Российской Федерации, осуществляемого уполномоченным органом государственной власти субъекта Российской Федерации, на который возложено государственное регулирование в области культуры, в соответствии с положением, утверждаемым высшим исполнительным органом государственной власти субъекта Российской Федерации.\nПредметом федерального государственного контроля (надзора) за состоянием Музейного фонда Российской Федерации является соблюдение юридическими лицами, за исключением государственных музеев, находящихся в ведении субъектов Российской Федерации, и гражданами, в собственности, оперативном управлении или пользовании которых находятся музейные предметы и музейные коллекции, установленных настоящим Федеральным законом и принимаемыми в соответствии с ним иными нормативными правовыми актами Российской Федерации обязательных требований к обеспечению хранения, изучения, комплектования, учета и использования музейных предметов и музейных коллекций, включенных в состав государственной части и состав негосударственной части Музейного фонда Российской Федерации.\nПредметом регионального государственного контроля (надзора) за состоянием Музейного фонда Российской Федерации является соблюдение государственными музеями, находящимися в ведении субъектов Российской Федерации, в собственности, оперативном управлении или пользовании которых находятся музейные предметы и музейные коллекции, установленных настоящим Федеральным законом и принимаемыми в соответствии с ним иными нормативными правовыми актами обязательных требований к обеспечению хранения, изучения, комплектования, учета и использования музейных предметов и музейных коллекций, включенных в состав государственной части Музейного фонда Российской Федерации.\nОрганизация и осуществление государственного контроля (надзора) за состоянием Музейного фонда Российской Федерации регулируются Федеральным законом от 31 июля 2020 года № 248-ФЗ \"О государственном контроле (надзоре) и муниципальном контроле в Российской Федерации\".\n(Дополнение статьей - Федеральный закон от 11.06.2021 № 170-ФЗ)"],
["13","Состав государственной части Музейного фонда Российской Федерации","ГЛАВА III. ГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 13. Состав государственной части Музейного фонда Российской Федерации\nВ состав государственной части Музейного фонда Российской Федерации входят музейные предметы и музейные коллекции, находящиеся в федеральной собственности и в собственности субъектов Российской Федерации, независимо от того, в чьем владении они находятся.\nМузейные предметы и музейные коллекции, приобретаемые после вступления настоящего Федерального закона в силу государственными музеями и иными государственными организациями за счет средств учредителей либо за счет собственных или иных средств, входят в состав государственной части Музейного фонда Российской Федерации. (В редакции Федерального закона от 03.07.2016 № 357-ФЗ)"],
["14","Формы собственности на государственную часть Музейного фонда Российской Федерации","ГЛАВА III. ГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 14. Формы собственности на государственную часть Музейного фонда Российской Федерации\nМузейные предметы и музейные коллекции, включенные в состав государственной части Музейного фонда Российской Федерации, являются государственной собственностью. (В редакции Федерального закона от 03.07.2016 № 357-ФЗ)\nВ федеральной собственности находятся музейные предметы и музейные коллекции, которые хранятся в музеях и иных организациях и которые:\nнаходились в федеральной собственности (собственности бывшего СССР и бывшей РСФСР) до дня вступления в силу настоящего Федерального закона независимо от источников поступления или были приобретены за счет средств федерального бюджета (бюджетов бывшего СССР и бывшей РСФСР);\nприобретены государственными музеями и иными государственными организациями, находящимися в ведении Российской Федерации, по основаниям, предусмотренным законодательством Российской Федерации.\n(Часть в редакции Федерального закона от 03.07.2016 № 357-ФЗ)\nВ собственности субъектов Российской Федерации находятся музейные предметы и музейные коллекции, которые:\nнаходились в собственности субъектов Российской Федерации (автономных образований, городов республиканского подчинения, краев и областей бывшей РСФСР) до дня вступления в силу настоящего Федерального закона, а также были приобретены за счет средств их бюджетов;\nприобретены государственными музеями и иными государственными организациями, находящимися в ведении субъектов Российской Федерации, по основаниям, предусмотренным законодательством Российской Федерации.\n(Дополнение частью - Федеральный закон от 03.07.2016 № 357-ФЗ)\nМузейные предметы и музейные коллекции, включенные в состав государственной части Музейного фонда Российской Федерации, отчуждению из государственной собственности не подлежат. (Дополнение частью - Федеральный закон от 03.07.2016 № 357-ФЗ)"],
["15","(Статья утратила силу - Федеральный закон от 03.07.2016 № 357-ФЗ)","ГЛАВА III. ГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 15. (Статья утратила силу - Федеральный закон от 03.07.2016 № 357-ФЗ)"],
["16","Управление музейными предметами и музейными коллекциями, включенными в состав государственной части Музейного фонда Российской Федерации","ГЛАВА III. ГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2023-12-12","Статья 16. Управление музейными предметами и музейными коллекциями, включенными в состав государственной части Музейного фонда Российской Федерации\nУправление музейными предметами и музейными коллекциями, включенными в состав государственной части Музейного фонда Российской Федерации, осуществляется федеральным органом исполнительной власти в сфере культуры и органами исполнительной власти субъектов Российской Федерации, на которые возложено государственное регулирование в сфере культуры, в соответствии с их компетенцией.\nМузейные предметы и музейные коллекции, включенные в состав государственной части Музейного фонда Российской Федерации и находящиеся в государственной собственности, могут передаваться в безвозмездное пользование государственным и муниципальным музеям и другим организациям (включая религиозные) с разрешения федерального органа исполнительной власти в сфере культуры на основании соответствующих договоров в порядке, установленном Правительством Российской Федерации. (В редакции Федерального закона от 12.12.2023 № 581-ФЗ)\nВключенные в состав государственной части Музейного фонда Российской Федерации музыкальные инструменты, относящиеся к государственной коллекции музыкальных инструментов, с разрешения федерального органа исполнительной власти в сфере культуры могут передаваться в пользование физическим лицам на основании соответствующих договоров в порядке, предусмотренном положением о государственной коллекции музыкальных инструментов.\nФормы договоров, указанных в настоящей статье, утверждаются федеральным органом исполнительной власти в сфере культуры.\n(Статья в редакции Федерального закона от 03.07.2016 № 357-ФЗ)"],
["17","(Статья утратила силу - Федеральный закон от 11.06.2021 № 170-ФЗ)","ГЛАВА III. ГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2021-06-11","Статья 17. (Статья утратила силу - Федеральный закон от 11.06.2021 № 170-ФЗ)"],
["18","Государственная поддержка государственной части Музейного фонда Российской Федерации и государственных музеев в Российской Федерации","ГЛАВА III. ГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 18. Государственная поддержка государственной части Музейного фонда Российской Федерации и государственных музеев в Российской Федерации\nПравительство Российской Федерации и органы исполнительной власти субъектов Российской Федерации обязаны обеспечивать финансовые и иные условия, необходимые для хранения и использования музейных предметов и музейных коллекций, входящих в состав государственной части Музейного фонда Российской Федерации и переданных в оперативное управление государственным музеям, иным государственным организациям, а также предоставлять необходимые гарантии возмещения ущерба, причиненного указанным музейным предметам и музейным коллекциям. (В редакции Федерального закона от 03.07.2016 № 357-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 22.08.2004 № 122-ФЗ)\nПравительство Российской Федерации и органы исполнительной власти субъектов Российской Федерации могут устанавливать особые формы поддержки государственных музеев в связи с необходимостью принятия дополнительных мер по сохранению уникальных историко-художественных комплексов, а также создания наиболее благоприятных условий для деятельности крупнейших государственных музеев в Российской Федерации, хранящих музейные предметы и музейные коллекции, имеющие мировое значение."],
["19","Состав негосударственной части Музейного фонда Российской Федерации","ГЛАВА IV. НЕГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","","Статья 19. Состав негосударственной части Музейного фонда Российской Федерации\nМузейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации и не относящиеся к его государственной части, составляют негосударственную часть Музейного фонда Российской Федерации."],
["20","(Статья утратила силу - Федеральный закон от 03.07.2016 № 357-ФЗ)","ГЛАВА IV. НЕГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 20. (Статья утратила силу - Федеральный закон от 03.07.2016 № 357-ФЗ)"],
["21","(Статья утратила силу - Федеральный закон от 03.07.2016 № 357-ФЗ)","ГЛАВА IV. НЕГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 21. (Статья утратила силу - Федеральный закон от 03.07.2016 № 357-ФЗ)"],
["22","(Статья утратила силу - Федеральный закон от 03.07.2016 № 357-ФЗ)","ГЛАВА IV. НЕГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 22. (Статья утратила силу - Федеральный закон от 03.07.2016 № 357-ФЗ)"],
["23","(Статья утратила силу - Федеральный закон от 11.06.2021 № 170-ФЗ)","ГЛАВА IV. НЕГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2021-06-11","Статья 23. (Статья утратила силу - Федеральный закон от 11.06.2021 № 170-ФЗ)"],
["24","Поддержка негосударственной части Музейного фонда Российской Федерации и негосударственных музеев в Российской Федерации органами государственной власти и органами местного самоуправления","ГЛАВА IV. НЕГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 24. Поддержка негосударственной части Музейного фонда Российской Федерации и негосударственных музеев в Российской Федерации органами государственной власти и органами местного самоуправления\n(Наименование в редакции Федерального закона от 03.07.2016 № 357-ФЗ)\nОрганы государственной власти и органы местного самоуправления в пределах своих полномочий могут оказывать поддержку негосударственной части Музейного фонда Российской Федерации и негосударственным музеям в Российской Федерации в различных формах, в том числе:\nпредоставлять государственные реставрационные учреждения для проведения реставрации музейных предметов и музейных коллекций, включенных в состав негосударственной части Музейного фонда Российской Федерации;\nобеспечивать передачу, в случае необходимости, музейных предметов и музейных коллекций, включенных в состав негосударственной части Музейного фонда Российской Федерации, на хранение в государственные хранилища;\nАбзац. (Утратил силу - Федеральный закон от 22.08.2004 № 122-ФЗ)\nАбзац. (Утратил силу - Федеральный закон от 22.08.2004 № 122-ФЗ)"],
["25","Сделки с музейными предметами и музейными коллекциями, включенными в состав негосударственной части Музейного фонда Российской Федерации","ГЛАВА IV. НЕГОСУДАРСТВЕННАЯ ЧАСТЬ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 25. Сделки с музейными предметами и музейными коллекциями, включенными в состав негосударственной части Музейного фонда Российской Федерации\nПри совершении сделок с музейными предметами и музейными коллекциями, включенными в состав негосударственной части Музейного фонда Российской Федерации, сторона, у которой возникают гражданские права и обязанности в отношении этих музейных предметов и музейных коллекций, принимает на себя обязательства по соблюдению требований законодательства Российской Федерации о Музейном фонде Российской Федерации и музеях в Российской Федерации.\nПри совершении сделок, направленных на отчуждение музейных предметов и музейных коллекций, включенных в состав негосударственной части Музейного фонда Российской Федерации, государство имеет преимущественное право приобретения указанных музейных предметов и музейных коллекций. Порядок приобретения государством музейных предметов и музейных коллекций, включенных в состав негосударственной части Музейного фонда Российской Федерации, устанавливается Правительством Российской Федерации.\nЕсли собственник не исполняет обязательства, установленные частью первой настоящей статьи, государство имеет право осуществить выкуп бесхозяйственно содержимых музейных предметов и музейных коллекций, включенных в состав негосударственной части Музейного фонда Российской Федерации, в соответствии с гражданским законодательством Российской Федерации.\nСобственник музейных предметов и музейных коллекций, включенных в состав негосударственной части Музейного фонда Российской Федерации, обязан уведомить федеральный орган исполнительной власти в сфере культуры о сделке, подлежащей регистрации в реестре сделок, в порядке, установленном положением о Музейном фонде.\nСведения о сделках с музейными предметами и музейными коллекциями, включенными в состав негосударственной части Музейного фонда Российской Федерации, опубликованию и распространению не подлежат, за исключением опубликования таких сведений по согласованной обеими сторонами сделки инициативе и в случаях, предусмотренных законодательством Российской Федерации.\nРеализация предусмотренных частями второй и третьей настоящей статьи преимущественного права приобретения или права выкупа бесхозяйственно содержимых музейных предметов и музейных коллекций, включенных в состав негосударственной части Музейного фонда Российской Федерации, от лица государства производится федеральным органом исполнительной власти в сфере культуры либо органами исполнительной власти субъектов Российской Федерации, на которые возложено государственное регулирование в сфере культуры, в порядке, установленном Правительством Российской Федерации.\n(Статья в редакции Федерального закона от 03.07.2016 № 357-ФЗ)"],
["26","Создание музеев в Российской Федерации","ГЛАВА V. МУЗЕИ В РОССИЙСКОЙ ФЕДЕРАЦИИ","","Статья 26. Создание музеев в Российской Федерации\nМузеи в Российской Федерации создаются в форме учреждений для осуществления культурных, образовательных и научных функций некоммерческого характера."],
["26.1","Музеи-заповедники","ГЛАВА V. МУЗЕИ В РОССИЙСКОЙ ФЕДЕРАЦИИ","2018-12-27","Статья 26.1. Музеи-заповедники\nМузей-заповедник - музей, которому в установленном порядке предоставлены земельные участки с расположенными на них достопримечательными местами, отнесенными к историко-культурным заповедникам, или ансамблями.\nТерриторией музея-заповедника являются земельные участки, указанные в части первой настоящей статьи, иные земельные участки, предоставленные музею-заповеднику в установленном порядке в связи с созданием данного музея-заповедника, а также в период его деятельности. Территория музея-заповедника может включать в себя водный объект, участок береговой полосы водного объекта, либо территория музея-заповедника может примыкать к участку береговой полосы расположенного вне границ территории музея-заповедника водного объекта. (В редакции Федерального закона от 27.12.2018 № 515-ФЗ)\nНаряду с видами деятельности, осуществляемыми музеями в соответствии с настоящим Федеральным законом, другими федеральными законами и иными нормативными правовыми актами Российской Федерации, законами и иными нормативными правовыми актами субъектов Российской Федерации, музей-заповедник обеспечивает сохранность переданных ему объектов культурного наследия и доступ к ним граждан, а также осуществляет сохранение, изучение и популяризацию указанных объектов.\nМузей-заповедник также вправе:\nосуществлять деятельность, направленную на сохранение в границах территории музея-заповедника исторически сложившихся видов деятельности (в том числе поддержание традиционного образа жизни и природопользования), осуществляемых сложившимися, характерными для данной территории способами, народных художественных промыслов и ремесел;\nосуществлять экскурсионное обслуживание и предоставлять информационные услуги;\nсоздавать условия для туристской деятельности;\nпроводить природоохранные мероприятия;\nосуществлять деятельность по содержанию и эксплуатации объектов инфраструктуры (в том числе зданий, жилых помещений и нежилых помещений), транспортных средств, необходимых музею-заповеднику для обеспечения доступа граждан к предоставленным ему объектам культурного наследия, осуществления экскурсионного обслуживания, создания условий для туристской деятельности.\nПравила посещения музея-заповедника устанавливаются музеем-заповедником и доводятся до сведения граждан путем размещения на официальном сайте музея-заповедника в информационно-телекоммуникационной сети \"Интернет\", в зоне организации приема посетителей музея-заповедника, в иных доступных для них местах на территории музея-заповедника. (Дополнение частью - Федеральный закон от 27.12.2018 № 515-ФЗ)\nПравила посещения музея-заповедника включают в себя в том числе:\nособенности использования расположенных на территории музея-заповедника водного объекта, участка береговой полосы водного объекта, а также расположенного вне границ территории музея-заповедника водного объекта, к участку береговой полосы которого примыкает территория музея-заповедника;\nособенности доступа к расположенным на территории музея-заповедника водному объекту, участку береговой полосы водного объекта, а также к участку береговой полосы, к которому примыкает территория музея-заповедника, водного объекта, расположенного вне границ территории музея-заповедника;\nправила поведения посетителей музея-заповедника на территории музея-заповедника и на объектах, которые на ней расположены;\nправила поведения граждан на примыкающем к территории музея-заповедника участке береговой полосы расположенного вне границ территории музея-заповедника водного объекта;\nиную необходимую для посетителей музея-заповедника информацию.\n(Дополнение частью - Федеральный закон от 27.12.2018 № 515-ФЗ)\nГраждане, постоянно проживающие на территории музея-заповедника, в границах его территории имеют право на осуществление деятельности, направленной на обеспечение своей жизнедеятельности, в том числе деятельности, требующей их свободного доступа к расположенному на территории музея-заповедника водному объекту, участку береговой полосы такого водного объекта, а также к участку береговой полосы, к которому примыкает территория музея-заповедника, водного объекта, расположенного вне границ территории музея-заповедника. В границах территории музея-заповедника допускается деятельность постоянно проживающих на его территории граждан, направленная на сохранение исторически сложившихся видов деятельности, осуществляемых сложившимися, характерными для данной территории способами, в том числе с использованием водных объектов, их частей. (Дополнение частью - Федеральный закон от 27.12.2018 № 515-ФЗ)\n(Дополнение статьей - Федеральный закон от 23.02.2011 № 19-ФЗ)"],
["27","Цели создания музеев в Российской Федерации","ГЛАВА V. МУЗЕИ В РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 27. Цели создания музеев в Российской Федерации\nЦелями создания музеев в Российской Федерации являются:\nосуществление просветительной, научно-исследовательской и образовательной деятельности;\nхранение музейных предметов и музейных коллекций;\nвыявление и собирание музейных предметов и музейных коллекций;\nизучение музейных предметов и музейных коллекций;\nпубликация музейных предметов и музейных коллекций.\nЦелями создания музеев-заповедников в Российской Федерации наряду с целями, указанными в части первой настоящей статьи, являются также обеспечение сохранности переданных музею-заповеднику объектов культурного наследия и доступа к ним граждан, осуществление сохранения, изучения и популяризации указанных объектов. (В редакции Федерального закона от 03.07.2016 № 357-ФЗ)\nЦелями создания музеев-заповедников в Российской Федерации наряду с целями, указанными в частях первой и второй настоящей статьи, могут являться обеспечение режима содержания достопримечательного места, отнесенного к историко-культурному заповеднику, или ансамбля, сохранение в границах территории музея-заповедника исторически сложившихся видов деятельности (в том числе поддержание традиционного образа жизни и природопользования), осуществляемых сложившимися, характерными для данной территории способами, народных художественных промыслов и ремесел, осуществление экскурсионного обслуживания, предоставление информационных услуг, а также создание условий для туристской деятельности.\nМузеи, в том числе музеи-заповедники, наряду с деятельностью, направленной на достижение целей, указанных в частях первой - третьей настоящей статьи, могут осуществлять образовательную деятельность в соответствии с законодательством Российской Федерации об образовании. (Дополнение частью - Федеральный закон от 03.07.2016 № 357-ФЗ)\nСоздание музеев в Российской Федерации для иных целей не допускается.\n(Статья в редакции Федерального закона от 23.02.2011 № 19-ФЗ)"],
["28","Порядок учреждения музеев в Российской Федерации","ГЛАВА V. МУЗЕИ В РОССИЙСКОЙ ФЕДЕРАЦИИ","","Статья 28. Порядок учреждения музеев в Российской Федерации\nМузеи в Российской Федерации учреждаются в порядке, установленном законодательством Российской Федерации."],
["29","Порядок учреждения государственных музеев в Российской Федерации","ГЛАВА V. МУЗЕИ В РОССИЙСКОЙ ФЕДЕРАЦИИ","2010-05-08","Статья 29. Порядок учреждения государственных музеев в Российской Федерации\nГосударственные музеи, находящиеся в ведении Российской Федерации, создаются, реорганизуются и ликвидируются в порядке, определенном Правительством Российской Федерации, если иное не установлено федеральными законами и указами Президента Российской Федерации. Создание, реорганизация и ликвидация государственных музеев, находящихся в ведении субъектов Российской Федерации, осуществляется в порядке, определенном высшим исполнительным органом государственной власти субъекта Российской Федерации, если иное не установлено законами субъекта Российской Федерации. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\nЧасть. (Утратила силу - Федеральный закон от 08.05.2010 № 83-ФЗ)\nНедвижимое имущество, закрепленное за государственными музеями на праве оперативного управления, может быть изъято собственником только в случае использования этого имущества не по назначению либо в случае ликвидации музея.\nВ случае сдачи в аренду недвижимого имущества, закрепленного за государственными музеями на праве оперативного управления, арендные платежи остаются в распоряжении музея (за исключением музея, являющегося казенным учреждением) и направляются исключительно на поддержание технического состояния данного недвижимого имущества. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\nЗемельные участки, на которых расположены государственные музеи, предоставляются им на праве постоянного (бессрочного) пользования. (В редакции Федерального закона от 26.06.2007 № 118-ФЗ)"],
["30","Порядок учреждения негосударственных музеев в Российской Федерации","ГЛАВА V. МУЗЕИ В РОССИЙСКОЙ ФЕДЕРАЦИИ","2017-12-28","Статья 30. Порядок учреждения негосударственных музеев в Российской Федерации\nУчредителями негосударственных музеев могут быть органы местного самоуправления, физические и юридические лица.\nНегосударственные музеи создаются в форме учреждения органами местного самоуправления, физическими или юридическими лицами в соответствии с законодательством Российской Федерации.\nЗакрепление музейных предметов и музейных коллекций за негосударственными музеями производится собственником после их включения в государственный каталог в соответствии с законодательством Российской Федерации на праве оперативного управления.\nУставы негосударственных музеев утверждаются их учредителями и регистрируются в установленном порядке.\nНедвижимое имущество, закрепленное за негосударственными музеями на праве оперативного управления, может быть изъято собственником только в случае использования этого имущества не по назначению либо в случае ликвидации музея.\nПравительство Российской Федерации по представлению федерального органа исполнительной власти в сфере культуры в соответствии с утверждаемым Правительством Российской Федерации порядком может предоставить негосударственному музею статус негосударственного музея федерального значения.\n(Статья в редакции Федерального закона от 28.12.2017 № 435-ФЗ)"],
["31","Реорганизация музеев в Российской Федерации","ГЛАВА V. МУЗЕИ В РОССИЙСКОЙ ФЕДЕРАЦИИ","","Статья 31. Реорганизация музеев в Российской Федерации\nРеорганизация музеев в Российской Федерации производится в соответствии с гражданским законодательством Российской Федерации.\nИзменение целей деятельности музеев в результате реорганизации не допускается."],
["32","Ликвидация музеев в Российской Федерации","ГЛАВА V. МУЗЕИ В РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 32. Ликвидация музеев в Российской Федерации\nЛиквидация музеев в Российской Федерации осуществляется в соответствии с гражданским законодательством Российской Федерации.\nПри ликвидации государственных и муниципальных музеев, иных государственных и муниципальных организаций музейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации и находящиеся в указанных музеях и организациях на праве оперативного управления или в безвозмездном пользовании, передаются в оперативное управление или в безвозмездное пользование в другие государственные и муниципальные музеи, государственные и муниципальные организации, осуществляющие хранение музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации, в порядке, установленном положением о Музейном фонде:\nпо решению федерального органа исполнительной власти в сфере культуры - в отношении музейных предметов и музейных коллекций, находящихся в федеральной собственности;\nпо решению органа исполнительной власти субъекта Российской Федерации, согласованному с федеральным органом исполнительной власти в сфере культуры, - в отношении музейных предметов и музейных коллекций, находящихся в собственности субъекта Российской Федерации;\nпо решению органа местного самоуправления, согласованному с федеральным органом исполнительной власти в сфере культуры, - в отношении музейных предметов и музейных коллекций, находящихся в муниципальной собственности.\nСобственник включенных в негосударственную часть Музейного фонда Российской Федерации и находящихся в частной собственности музейных предметов и музейных коллекций при ликвидации музея обязан уведомить федеральный орган исполнительной власти в области культуры о ликвидации музея и о лице, принявшем на себя гражданские права и обязанности в отношении этих музейных предметов и музейных коллекций, в порядке, установленном положением о Музейном фонде.\nДействие положений настоящей статьи распространяется на музеи и иные организации, в собственности, во владении или в пользовании которых находятся музейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации.\n(Статья в редакции Федерального закона от 03.07.2016 № 357-ФЗ)"],
["33","Виды деятельности музеев в Российской Федерации","ГЛАВА V. МУЗЕИ В РОССИЙСКОЙ ФЕДЕРАЦИИ","2010-05-08","Статья 33. Виды деятельности музеев в Российской Федерации\nМузеи в Российской Федерации в соответствии со своими учредительными документами могут осуществлять деятельность, не запрещенную законодательством Российской Федерации и соответствующую целям деятельности музеев в Российской Федерации, которые предусмотрены настоящим Федеральным законом. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)\nМузеи в Российской Федерации в соответствии со своими учредительными документами могут осуществлять приносящую доходы деятельность лишь постольку, поскольку это служит достижению целей, предусмотренных настоящим Федеральным законом. (В редакции Федерального закона от 08.05.2010 № 83-ФЗ)"],
["34","(Статья исключена - Федеральный закон от 10.01.2003 № 15-ФЗ)","ГЛАВА V. МУЗЕИ В РОССИЙСКОЙ ФЕДЕРАЦИИ","2003-01-10","Статья 34. (Статья исключена - Федеральный закон от 10.01.2003 № 15-ФЗ)"],
["35","Доступ к музейным предметам и музейным коллекциям","ГЛАВА VI. ОБЕСПЕЧЕНИЕ ДОСТУПНОСТИ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 35. Доступ к музейным предметам и музейным коллекциям\nМузейные предметы и музейные коллекции, включенные в состав Музейного фонда Российской Федерации и находящиеся в музеях в Российской Федерации, открыты для доступа граждан.\nСобственником или владельцем могут устанавливаться ограничения доступа к музейным предметам и музейным коллекциям, включенным в состав Музейного фонда Российской Федерации и находящимся в музеях, по следующим основаниям:\nнеудовлетворительное состояние сохранности музейных предметов и музейных коллекций;\nпроизводство реставрационных работ;\nнахождение музейного предмета или музейной коллекции в хранилище (депозитарии) музея; (В редакции Федерального закона от 03.07.2016 № 357-ФЗ)\nиные предусмотренные законодательством Российской Федерации основания. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 357-ФЗ)\nМузеи организовывают и обеспечивают доступ граждан к музейным предметам и музейным коллекциям в соответствии с законодательством Российской Федерации в порядке, установленном положением о Музейном фонде и иными нормативными актами федерального органа исполнительной власти в сфере культуры. Порядок и условия доступа к музейным предметам и музейным коллекциям доводятся музеями до сведения граждан. (В редакции Федерального закона от 03.07.2016 № 357-ФЗ)\nПорядок обеспечения условий доступности для инвалидов музеев, включая возможность ознакомления с музейными предметами и музейными коллекциями, в соответствии с законодательством Российской Федерации о социальной защите инвалидов определяется федеральным органом исполнительной власти в сфере культуры по согласованию с федеральным органом исполнительной власти, осуществляющим функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере социальной защиты населения. (Дополнение частью - Федеральный закон от 01.12.2014 № 419-ФЗ) (В редакции Федерального закона от 03.07.2016 № 357-ФЗ)\nОграничение доступа к музейным предметам и музейным коллекциям из соображений цензуры не допускается."],
["36","Публикация музейных предметов и музейных коллекций","ГЛАВА VI. ОБЕСПЕЧЕНИЕ ДОСТУПНОСТИ МУЗЕЙНОГО ФОНДА РОССИЙСКОЙ ФЕДЕРАЦИИ","","Статья 36. Публикация музейных предметов и музейных коллекций\nПраво первой публикации музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации и находящихся в музеях в Российской Федерации, принадлежит музею, за которым закреплены данные музейные предметы и музейные коллекции.\nПередача прав на использование в коммерческих целях воспроизведений музейных предметов и музейных коллекций, включенных в состав Музейного фонда Российской Федерации и находящихся в музеях в Российской Федерации, осуществляется музеями в порядке, установленном собственником музейных предметов и музейных коллекций.\nПроизводство изобразительной, печатной, сувенирной и другой тиражированной продукции и товаров народного потребления с использованием изображений музейных предметов и музейных коллекций, зданий музеев, объектов, расположенных на территориях музеев, а также с использованием их названий и символики осуществляется с разрешения дирекций музеев."],
["37","Ответственность за нарушение законодательства Российской Федерации о Музейном фонде Российской Федерации и музеях в Российской Федерации","ГЛАВА VII. ОТВЕТСТВЕННОСТЬ ЗА НАРУШЕНИЕ ЗАКОНОДАТЕЛЬСТВА РОССИЙСКОЙ ФЕДЕРАЦИИ О МУЗЕЙНОМ ФОНДЕ РОССИЙСКОЙ ФЕДЕРАЦИИ И МУЗЕЯХ В РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 37. Ответственность за нарушение законодательства Российской Федерации о Музейном фонде Российской Федерации и музеях в Российской Федерации\nФизические и юридические лица, органы государственной власти и органы местного самоуправления, виновные в нарушении законодательства Российской Федерации о Музейном фонде Российской Федерации и музеях в Российской Федерации, несут административную, гражданско-правовую или уголовную ответственность в соответствии с законодательством Российской Федерации.\n(Статья в редакции Федерального закона от 03.07.2016 № 357-ФЗ)"],
["38","Ответственность должностных лиц","ГЛАВА VII. ОТВЕТСТВЕННОСТЬ ЗА НАРУШЕНИЕ ЗАКОНОДАТЕЛЬСТВА РОССИЙСКОЙ ФЕДЕРАЦИИ О МУЗЕЙНОМ ФОНДЕ РОССИЙСКОЙ ФЕДЕРАЦИИ И МУЗЕЯХ В РОССИЙСКОЙ ФЕДЕРАЦИИ","2016-07-03","Статья 38. Ответственность должностных лиц\nНевыполнение должностными лицами положений настоящего Федерального закона, а именно:\nнезаконный отказ от включения музейного предмета в состав Музейного фонда Российской Федерации;\nнезаконное исключение музейного предмета из состава Музейного фонда Российской Федерации;\nразглашение конфиденциальных сведений о музейных предметах, включенных в состав негосударственной части Музейного фонда Российской Федерации;\nнеправомерный отказ в регистрации сделок с музейными предметами - (В редакции Федерального закона от 10.01.2003 № 15-ФЗ)\nабзац (Исключен - Федеральный закон от 10.01.2003 № 15-ФЗ)\nвлечет административную ответственность в соответствии с законодательством Российской Федерации.\nОтветственность за своевременную постановку на государственный учет музейных предметов и музейных коллекций, подлежащих внесению в государственный каталог, и за достоверность сведений о них несет руководитель музея или иной организации, в собственности или во владении которых они находятся. (Дополнение частью - Федеральный закон от 03.07.2016 № 357-ФЗ)"],
["39","Вступление в силу настоящего Федерального закона","ГЛАВА VIII. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","","Статья 39. Вступление в силу настоящего Федерального закона\nНастоящий Федеральный закон вступает в силу со дня его официального опубликования."],
["40","Приведение нормативных правовых актов в соответствие с настоящим Федеральным законом","ГЛАВА VIII. ЗАКЛЮЧИТЕЛЬНЫЕ ПОЛОЖЕНИЯ","","Статья 40. Приведение нормативных правовых актов в соответствие с настоящим Федеральным законом\nПредложить Президенту Российской Федерации и поручить Правительству Российской Федерации привести свои нормативные правовые акты в соответствие с настоящим Федеральным законом.\nПрезидент Российской Федерации Б.Ельцин\nМосква, Кремль 26 мая 1996 года № 54-ФЗ"]
];
